 63	async function validateBenchmark(): Promise<void> {
 64	  const benchmarkId = args[1];
 65	  const sandboxDir = args[2];
 66	
 67	  if (!benchmarkId || !sandboxDir) {
 68	    console.error(chalk.red("Error: benchmark ID and sandbox directory required"));
 69	    process.exit(1);
 70	  }
 71	
 72	  const benchmark = benchmarks.find((b) => b.id === benchmarkId);
 73	  if (!benchmark) {
 74	    console.error(chalk.red(`Error: benchmark "${benchmarkId}" not found`));
 75	    process.exit(1);
 76	  }
 77	
 78	  try {
 79	    const modelArg = args.find((a) => a.startsWith("--model="))?.split("=")[1];
 80	    const meta = {
 81	      model: modelArg || "unknown-model",
 82	      stdout: "",
 83	      stderr: "",
 84	      exitCode: 0,
 85	      duration: 0,
 86	      commandsRun: [] as string[],
 87	      packagesInstalled: [] as string[],
 88	    };
 89	
 90	    const result = await validateSandbox(benchmark, sandboxDir, meta);
 91	    printBenchmarkResult(result, true);
 92	
