104	async function generateReport(): Promise<void> {
105	  const resultsDir = args[1];
106	  if (!resultsDir) {
107	    console.error(chalk.red("Error: results directory required"));
108	    process.exit(1);
109	  }
110	
111	  try {
112	    const files = await fs.readdir(resultsDir);
113	    const jsonFiles = files.filter((f) => f.endsWith(".json") && !f.startsWith("report-"));
114	
115	    if (jsonFiles.length === 0) {
116	      console.error(chalk.red("No result files found"));
117	      process.exit(1);
118	    }
119	
120	    const results = [];
121	    for (const file of jsonFiles) {
122	      const content = await fs.readFile(join(resultsDir, file), "utf-8");
123	      results.push(JSON.parse(content));
124	    }
125	
126	    const modelArg = args.find((a) => a.startsWith("--model="))?.split("=")[1];
127	    const suite = calculateSuiteResults(results, modelArg || "unknown-model");
128	    printSuiteReport(suite);
129	
130	    const reportFile = join(resultsDir, `report-${Date.now()}.json`);
131	    await exportResultsJson(suite, reportFile);
132	    console.log(chalk.gray(`Report saved to: ${reportFile}`));
133	  } catch (error) {
134	    console.error(chalk.red(`Error generating report: ${error}`));
135	    process.exit(1);
136	  }
137	}
