139	async function main(): Promise<void> {
140	  if (!command) {
141	    console.log(chalk.bold("Usage:"));
142	    console.log("  tsx src/cli.ts list [--category=X]");
143	    console.log("  tsx src/cli.ts prepare <id> [--model=X]");
144	    console.log("  tsx src/cli.ts validate <id> <sandboxDir>");
