 12	export async function prepareSandbox(
 13	  benchmark: Benchmark,
 14	  baseDir?: string
 15	): Promise<string> {
 16	  const tmpBase = baseDir || tmpdir();
 17	  const sandboxName = `benchmark-${randomBytes(8).toString("hex")}`;
 18	  const sandboxDir = join(tmpBase, sandboxName);
 19	
 20	  await fs.mkdir(sandboxDir, { recursive: true });
 21	
 22	  if (benchmark.fixtures && benchmark.fixtures.length > 0) {
 23	    for (const fixture of benchmark.fixtures) {
 24	      const filePath = resolve(sandboxDir, fixture.filename);
 25	      if (!filePath.startsWith(resolve(sandboxDir))) {
 26	        throw new Error(`Path traversal detected in fixture: ${fixture.filename}`);
 27	      }
 28	      const dirPath = dirname(filePath);
 29	
 30	      await fs.mkdir(dirPath, { recursive: true });
 31	      await fs.writeFile(filePath, fixture.content, {
 32	        encoding: fixture.encoding || "utf-8",
 33	      });
 34	    }
 35	  }
 36	
 37	  return sandboxDir;
 38	}
