 40	export async function validateSandbox(
 41	  benchmark: Benchmark,
 42	  sandboxDir: string,
 43	  meta: {
 44	    model: string;
 45	    stdout: string;
 46	    stderr: string;
 47	    exitCode: number;
 48	    duration: number;
 49	    commandsRun: string[];
 50	    packagesInstalled: string[];
 51	  }
 52	): Promise<BenchmarkResult> {
 53	  let outputFiles: string[] = [];
 54	
 55	  try {
 56	    outputFiles = await listFilesRecursive(sandboxDir);
 57	  } catch {
 58	    outputFiles = [];
 59	  }
 60	
 61	  const context: ValidationContext = {
 62	    sandboxDir,
 63	    outputFiles,
 64	    stdout: meta.stdout,
 65	    stderr: meta.stderr,
 66	    exitCode: meta.exitCode,
 67	    duration: meta.duration,
 68	    commandsRun: meta.commandsRun,
 69	    packagesInstalled: meta.packagesInstalled,
 70	  };
 71	
 72	  const validation = await benchmark.validate(context);
 73	
 74	  return {
 75	    benchmarkId: benchmark.id,
 76	    benchmarkName: benchmark.name,
 77	    category: benchmark.category,
 78	    difficulty: benchmark.difficulty,
 79	    model: meta.model || "unknown",
 80	    passed: validation.passed,
 81	    score: validation.score,
 82	    reason: validation.reason,
 83	    duration: meta.duration,
 84	    commandsRun: meta.commandsRun,
 85	    packagesInstalled: meta.packagesInstalled,
 86	    timestamp: new Date().toISOString(),
 87	    details: validation.details,
 88	  };
 89	}
