125	async function listFilesRecursive(dir: string): Promise<string[]> {
126	  const files: string[] = [];
127	
128	  async function walk(currentPath: string, prefix: string = ""): Promise<void> {
129	    const entries = await fs.readdir(currentPath, { withFileTypes: true });
130	
131	    for (const entry of entries) {
132	      const relativePath = prefix ? join(prefix, entry.name) : entry.name;
133	
134	      if (entry.isDirectory()) {
135	        await walk(join(currentPath, entry.name), relativePath);
136	      } else {
137	        files.push(relativePath);
138	      }
139	    }
140	  }
141	
142	  await walk(dir);
143	  return files;
144	}
