 16	export function printBenchmarkResult(result: BenchmarkResult, verbose?: boolean): void {
 17	  const statusLabel = result.passed ? chalk.green("PASS") : chalk.red("FAIL");
 18	  const scoreColor = result.score === "3" ? chalk.cyan : result.score === "0" ? chalk.red : chalk.yellow;
 19	  const scoreLabel = scoreColor(`${result.score}/3`);
 20	  const categoryLabel = chalk.gray(`(${result.category})`);
 21	
 22	  let line = `${statusLabel} ${scoreLabel} ${result.benchmarkName} ${categoryLabel} - ${result.reason}`;
 23	
 24	  if (verbose) {
 25	    line += ` [${result.duration}ms]`;
 26	  }
 27	
 28	  console.log(line);
 29	}
