 31	export function printSuiteReport(suite: BenchmarkSuite): void {
 32	  console.log(chalk.bold("\n=== Benchmark Suite Report ===\n"));
 33	  console.log(chalk.blue(`Model: ${suite.model}`));
 34	  console.log(chalk.blue(`Timestamp: ${suite.timestamp}`));
 35	
 36	  console.log(chalk.bold("\n--- Results by Category ---\n"));
 37	
 38	  const categories = Object.entries(suite.byCategory);
 39	  let maxCategoryLength = 0;
 40	  categories.forEach(([cat]) => {
 41	    if (cat.length > maxCategoryLength) maxCategoryLength = cat.length;
 42	  });
 43	
 44	  categories.forEach(([category, result]) => {
 45	    const percentage = ((result.avgScore / 3) * 100).toFixed(1);
 46	    const passStatus = `${result.passed}/${result.total}`;
 47	    const categoryPad = category.padEnd(maxCategoryLength);
 48	    console.log(
 49	      `  ${categoryPad}  ${passStatus.padEnd(8)}  avg: ${result.avgScore.toFixed(2)}/3 (${percentage}%)`
 50	    );
 51	  });
 52	
 53	  console.log(chalk.bold("\n--- Overall Score ---\n"));
 54	  const agencyPercentage = (suite.agencyIndex * 100).toFixed(1);
 55	  console.log(`  Total Score: ${chalk.cyan(suite.totalScore.toString())} / ${suite.maxScore}`);
 56	  console.log(`  Agency Index: ${chalk.cyan(agencyPercentage + "%")}`);
 57	
 58	  const activeCategories = categories.filter(([, cat]) => cat.total > 0);
 59	  if (activeCategories.length === 0) return;
 60	
 61	  const bestCategory = activeCategories.reduce((best, [name, cat]) =>
 62	    cat.avgScore > best[1].avgScore ? [name, cat] : best
 63	  );
 64	  const worstCategory = activeCategories.reduce((worst, [name, cat]) =>
 65	    cat.avgScore < worst[1].avgScore ? [name, cat] : worst
 66	  );
 67	
 68	  console.log(chalk.bold("\n--- Highlights ---\n"));
 69	  console.log(chalk.green(`  Best: ${bestCategory[0]} (${bestCategory[1].avgScore.toFixed(2)}/3)`));
 70	  console.log(chalk.yellow(`  Worst: ${worstCategory[0]} (${worstCategory[1].avgScore.toFixed(2)}/3)`));
 71	  console.log();
 72	}
