 74	export function printComparisonReport(comparison: ModelComparison): void {
 75	  console.log(chalk.bold("\n=== Model Comparison Report ===\n"));
 76	  console.log(chalk.blue(`Timestamp: ${comparison.timestamp}`));
 77	
 78	  const sorted = [...comparison.models].sort((a, b) => b.agencyIndex - a.agencyIndex);
 79	
 80	  console.log(chalk.bold("\n--- Rankings ---\n"));
 81	  sorted.forEach((model, idx) => {
 82	    const rank = idx + 1;
 83	    const agencyPercentage = (model.agencyIndex * 100).toFixed(1);
 84	    const medal = rank === 1 ? "🥇" : rank === 2 ? "🥈" : rank === 3 ? "🥉" : "  ";
 85	    console.log(
 86	      `  #${rank} ${medal} ${chalk.cyan(model.model.padEnd(20))} ${agencyPercentage}% (${model.totalScore}/${model.maxScore})`
 87	    );
 88	  });
 89	
 90	  console.log(chalk.bold("\n--- Per-Category Breakdown ---\n"));
 91	
 92	  const categories: Set<BenchmarkCategory> = new Set();
 93	  sorted.forEach((model) => {
 94	    const categoryMap = new Map<BenchmarkCategory, { passed: number; total: number; avgScore: number }>();
 95	    model.results.forEach((result) => {
 96	      categories.add(result.category);
 97	      const existing = categoryMap.get(result.category) || { passed: 0, total: 0, avgScore: 0 };
 98	      categoryMap.set(result.category, {
 99	        passed: existing.passed + (result.passed ? 1 : 0),
100	        total: existing.total + 1,
101	        avgScore: existing.avgScore + parseFloat(result.score),
102	      });
103	    });
104	
105	    Array.from(categories).forEach((cat) => {
106	      const catData = categoryMap.get(cat);
107	      if (catData) {
108	        const avg = (catData.avgScore / catData.total).toFixed(2);
109	        const percentage = ((parseFloat(avg) / 3) * 100).toFixed(0);
110	        console.log(
111	          `  ${model.model.padEnd(15)} ${cat.padEnd(18)} ${catData.passed}/${catData.total} passed (avg: ${avg}/3, ${percentage}%)`
112	        );
113	      }
114	    });
115	    console.log();
116	  });
117	}
