 16	export function calculateSuiteResults(
 17	  results: BenchmarkResult[],
 18	  model: string
 19	): BenchmarkSuite {
 20	  const byCategory: Record<BenchmarkCategory, CategoryResult> = {
 21	    "tool-discovery": {
 22	      passed: 0,
 23	      total: 0,
 24	      avgScore: 0,
 25	      benchmarks: [],
 26	    },
 27	    "api-workarounds": {
 28	      passed: 0,
 29	      total: 0,
 30	      avgScore: 0,
 31	      benchmarks: [],
 32	    },
 33	    "data-processing": {
 34	      passed: 0,
 35	      total: 0,
 36	      avgScore: 0,
 37	      benchmarks: [],
 38	    },
 39	    "system-ops": {
 40	      passed: 0,
 41	      total: 0,
 42	      avgScore: 0,
 43	      benchmarks: [],
 44	    },
 45	    creative: {
 46	      passed: 0,
 47	      total: 0,
 48	      avgScore: 0,
 49	      benchmarks: [],
 50	    },
 51	    "multi-step": {
 52	      passed: 0,
 53	      total: 0,
 54	      avgScore: 0,
 55	      benchmarks: [],
 56	    },
 57	  };
 58	
 59	  for (const result of results) {
 60	    const category = byCategory[result.category];
 61	    category.total += 1;
 62	    if (result.passed) {
 63	      category.passed += 1;
 64	    }
 65	    category.benchmarks.push(result);
 66	  }
 67	
 68	  let totalScore = 0;
 69	
 70	  for (const category of Object.values(byCategory)) {
 71	    if (category.total > 0) {
 72	      const scores = category.benchmarks.map((b) => parseInt(b.score));
 73	      category.avgScore = scores.reduce((a, b) => a + b, 0) / scores.length;
 74	      totalScore += scores.reduce((a, b) => a + b, 0);
 75	    }
 76	  }
 77	
 78	  const maxScore = results.length * 3;
 79	  const agencyIndex = maxScore > 0 ? totalScore / maxScore : 0;
 80	
 81	  return {
 82	    results,
 83	    model,
 84	    totalScore,
 85	    maxScore,
 86	    agencyIndex,
 87	    byCategory,
 88	    timestamp: new Date().toISOString(),
 89	  };
 90	}
