 92	export function compareModels(suites: BenchmarkSuite[]): ModelComparison {
 93	  const ranking = suites
 94	    .map((suite) => ({
 95	      model: suite.model,
 96	      agencyIndex: suite.agencyIndex,
 97	      totalScore: suite.totalScore,
 98	    }))
 99	    .sort((a, b) => b.agencyIndex - a.agencyIndex);
100	
101	  const categories: BenchmarkCategory[] = [
102	    "tool-discovery",
103	    "api-workarounds",
104	    "data-processing",
105	    "system-ops",
106	    "creative",
107	    "multi-step",
108	  ];
109	
110	  const byCategory: Record<
111	    BenchmarkCategory,
112	    Array<{ model: string; avgScore: number; passed: number }>
113	  > = {} as Record<
114	    BenchmarkCategory,
115	    Array<{ model: string; avgScore: number; passed: number }>
116	  >;
117	
118	  for (const category of categories) {
119	    byCategory[category] = suites
120	      .map((suite) => ({
121	        model: suite.model,
122	        avgScore: suite.byCategory[category].avgScore,
123	        passed: suite.byCategory[category].passed,
124	      }))
125	      .sort((a, b) => b.avgScore - a.avgScore);
126	  }
127	
128	  return {
129	    ranking,
130	    byCategory,
131	  };
132	}

